// Find the earliest Friday the 13th in the proleptic Gregorian calendar (from 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th ---
var earliest = Enumerable.Range(1, 12 * 400)
    .Select(i => new DateTime(1 + (i - 1) / 12, (i - 1) % 12 + 1, 13))
    .First(d => d.DayOfWeek == DayOfWeek.Friday);

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");

// --- Count in a full 400-year cycle (years 1–400) ---
int count = 0;
for (int year = 1; year <= 400; year++)
    for (int month = 1; month <= 12; month++)
        if (new DateTime(year, month, 13).DayOfWeek == DayOfWeek.Friday)
            count++;

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// --- Breakdown by month ---
Console.WriteLine("\nPer-month breakdown (400-year cycle):");
for (int month = 1; month <= 12; month++)
{
    int mc = Enumerable.Range(1, 400)
        .Count(y => new DateTime(y, month, 13).DayOfWeek == DayOfWeek.Friday);
    Console.WriteLine($"  {new DateTime(2000, month, 1):MMMM,-12} {mc}");
}

